const byte ENA=5, ENB=6, I1=7, I2=8, I3=11, I4=12, TRIG=9, ECHO=10;
bool turning=false; byte clearCount=0;
void drive(int l,int r) {
 analogWrite(ENA,0); analogWrite(ENB,0);
 digitalWrite(I1,l>0); digitalWrite(I2,l<0);
 digitalWrite(I3,r>0); digitalWrite(I4,r<0);
 analogWrite(ENA,abs(l)); analogWrite(ENB,abs(r));
}
void setup(){
 Serial.begin(115200);
 byte pins[]={ENA,ENB,I1,I2,I3,I4,TRIG};
 for(byte i=0;i<7;i++) pinMode(pins[i],OUTPUT);
 pinMode(ECHO,INPUT); drive(0,0); Serial.println("rover ready");
}
void loop(){
 digitalWrite(TRIG,LOW); delayMicroseconds(2);
 digitalWrite(TRIG,HIGH); delayMicroseconds(10); digitalWrite(TRIG,LOW);
 unsigned long us=pulseIn(ECHO,HIGH,30000);
 float cm=us/58.0;
 if(us==0 || cm<2){drive(0,0); clearCount=0; Serial.println("sensor fault STOP");}
 else {
  if(cm<40){turning=true;clearCount=0;}
  if(turning && cm>65){if(++clearCount>=3){turning=false;clearCount=0;}}
  else if(turning) clearCount=0;
  if(turning){drive(110,-110);Serial.println("AVOID");}
  else {drive(125,125);Serial.println("FORWARD");}
 }
 delay(65);
}

